const testRepoDir = "/tmp/git-test-repo";

describe("git operations", () => {
  beforeEach(() => {
    try {
      rmSync(testRepoDir, { recursive: true, force: true });
    } catch {
      // Ignore
    }
    mkdirSync(testRepoDir, { recursive: true });
  });

